/**
 * Shader of the sine grid.
 *
 * ## The mathematical idea
 *
 * A grid is not drawn, it is read: the distance to the nearest line is the
 * fractional part of the coordinates, recentred. To make each node oscillate,
 * the nodes are not moved — the domain is warped before being read. An offset
 * in sine of y on x, and in sine of x on y, with time in the phase: each node
 * traces a small loop, and the lines joining it bend with it.
 *
 * The moire comes from a second grid, read over the same domain but a little
 * finer, turned by a few degrees and warped in counter-phase. Where the two
 * networks coincide, the strokes add up; where they shift apart, they half
 * cancel. The resulting fringes move slowly — far more slowly than the nodes —
 * because they depend on the difference of the two warps, not on their sum.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the lines.
 * - `uColorC` — the nodes.
 * - `uCells` — number of cells across the height.
 * - `uAmplitude` — travel of the oscillation, in cells.
 * - `uSpeed` — speed of the oscillation.
 * - `uMoire` — weight of the second grid.
 */
export const SINE_GRID_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uCells;
uniform float uAmplitude;
uniform float uSpeed;
uniform float uMoire;

// Distance to the nearest line of a unit grid.
float gridDistance(vec2 q) {
  vec2 local = abs(fract(q + 0.5) - 0.5);
  return min(local.x, local.y);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float cells = clamp(uCells, 2.0, 40.0);
  vec2 p = vUv * vec2(aspect, 1.0) * cells;
  float t = uTime * uSpeed;

  // One pixel, in cell units.
  float px = cells / max(uResolution.y, 1.0);
  float amplitude = clamp(uAmplitude, 0.0, 0.5);

  // The domain is warped before it is read: each node traces a loop.
  vec2 q = p + amplitude * vec2(sin(p.y * 1.1 + t), sin(p.x * 0.9 - t * 1.3));

  float lines = 1.0 - smoothstep(px * 0.5, px * 1.5, gridDistance(q));
  float node = 1.0 - smoothstep(px * 2.0, px * 3.5, length(fract(q + 0.5) - 0.5));

  // The second grid: a little finer, turned, warped in counter-phase.
  float angle = 0.07;
  mat2 turn = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
  vec2 r = turn * p * 1.04;
  vec2 q2 = r + amplitude * vec2(sin(r.y * 1.1 - t), sin(r.x * 0.9 + t * 1.3));
  float lines2 = 1.0 - smoothstep(px * 0.5, px * 1.5, gridDistance(q2));

  float ink = clamp(lines * 0.7 + lines2 * uMoire * 0.5, 0.0, 1.0);

  vec3 colour = mix(uColorA, uColorB, ink);
  colour = mix(colour, uColorC, node);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Sine grid: a grid whose every node oscillates, and a light moire.
 *
 * ## The principle
 *
 * The nodes are not moved: the domain is warped by a sine before the grid is
 * read in it, and each node traces a small loop with the lines joining it. A
 * second grid, a little finer and turned by a few degrees, is superimposed in
 * counter-phase: its moire fringes move far more slowly than the nodes.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its
 * fallback. Reading the tokens, converting them to floats and re-reading them
 * when the theme changes all come from the engine — copying that here would
 * leave as many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { SINE_GRID_FRAGMENT } from './sine-grid.shader.js'

/** What the escape hatch receives. */
export interface SineGridControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface SineGridOwnProps {
  /** Number of cells across the height. Clamped to forty by the shader. @defaultValue 12 */
  cells?: number
  /** Travel of the oscillation, in cells. @defaultValue 0.18 */
  amplitude?: number
  /** Speed of the oscillation. @defaultValue 0.8 */
  speed?: number
  /** Weight of the second grid, the moire one. Zero puts it out. @defaultValue 0.6 */
  moire?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<SineGridControls>
}

/** All props. */
export type SineGridProps = Customisable<SineGridOwnProps>

/** Tokens used by default: the background, the lines, the nodes. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-theme-line',
  '--o-palette-brand-500',
] as const

/** Default fallback: a frozen tint, in the same tones. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Sine grid.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <SineGrid className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function SineGrid({
  cells = 12,
  amplitude = 0.18,
  speed = 0.8,
  moire = 0.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: SineGridProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: SINE_GRID_FRAGMENT,
    colors,
    uniforms: { uCells: cells, uAmplitude: amplitude, uSpeed: speed, uMoire: moire },
    name: 'sine-grid',
    // The second grid doubles the reads and, at a reduced pixel density, its
    // fringes shimmer: at low quality it is put out.
    degrade: (quality) => ({ uMoire: quality === 'low' ? 0 : moire }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
